place assets/world/cult/fire-basket.glb 12 0 312 270 1.0 cult_base
place assets/world/cult/banner.glb -8 0 252 0 1.0 cult_base
place assets/world/cult/banner.glb 8 0 252 180 1.0 cult_base
place assets/world/cult/banner.glb -14 0 272 0 1.0 cult_base
place assets/world/cult/banner.glb 14 0 272 180 1.0 cult_base
place assets/world/cult/banner.glb -10 0 326 0 1.0 cult_base
place assets/world/cult/banner.glb 10 0 326 180 1.0 cult_base
place assets/world/buildings/stone-wall-damaged.glb -46 0 268 90 1.0 cult_base
place assets/world/buildings/stone-wall-damaged.glb 46 0 268 90 1.0 cult_base
place assets/world/buildings/stone-wall-damaged.glb -46 0 332 0 1.0 cult_base
place assets/world/buildings/stone-wall-damaged.glb 46 0 332 0 1.0 cult_base

